// index is built once from generated+overrides, keyed by "METHOD PATH".
var index = buildIndex()

func buildIndex() map[string]string {
	m := make(map[string]string, len(generated)+len(overrides))
	for _, e := range generated {
		m[e.Method+" "+e.Path] = e.RiskClass
	}
	for _, e := range overrides {
		m[e.Method+" "+e.Path] = e.RiskClass
	}
	return m
}

// Lookup returns the risk class for method+path (path must be gin's route
// TEMPLATE, i.e. c.FullPath() -- ":param" placeholders literal, not the
// resolved request path), and whether an entry exists at all.
func Lookup(method, path string) (string, bool) {
	class, ok := index[method+" "+path]
	return class, ok
}

// All returns every classified (method, path, class) triple, for the
// coverage contract test and for documentation generation.
func All() []Entry {
	out := make([]Entry, 0, len(index))
	for key, class := range index {
		var method, path string
		for i := 0; i < len(key); i++ {
			if key[i] == ' ' {
				method, path = key[:i], key[i+1:]
				break
			}
		}
		out = append(out, Entry{Method: method, Path: path, RiskClass: class})
	}
	return out
}

// validRiskClasses is the same closed vocabulary
// TestRiskRegistry_EveryEntryIsAValidClass (internal/section28contract)
// already pins the generated+overrides tables against.
var validRiskClasses = map[string]bool{
	ratelimit.RiskLow: true, ratelimit.RiskStandard: true, ratelimit.RiskSensitive: true,
	ratelimit.RiskHighRisk: true, ratelimit.RiskInternalService: true,
}

// SelfCheck is a production-safe (no *testing.T, no test-only imports)
// well-formedness check: the registry actually loaded a non-trivial
// number of entries and every one carries a real, recognized risk class.
// It is NOT the full "every mounted route is covered" cross-reference
// internal/section28contract's TestRouteRiskRegistry_CoversEveryMountedRoute
// performs — that test enumerates every live feature's route manifest, a
// build-time/CI concern this package deliberately does not duplicate into
// the production binary (doing so would mean either importing a
// test-oriented package into cmd/main.go, or hand-duplicating ~30 manifest
// call sites here and risking exactly the kind of silent drift Section 28
// exists to catch). SelfCheck instead catches the failure mode a
// readiness probe can meaningfully detect at process startup: the
// registry ending up empty or corrupted (a bad merge, an init-order bug,
// a build that stripped the generated table) — used by cmd/main.go's
// "risk_registry" readiness check.
func SelfCheck() error {
	if len(index) == 0 {
		return fmt.Errorf("riskregistry: registry is empty")
	}
	for key, class := range index {
		if !validRiskClasses[class] {
			return fmt.Errorf("riskregistry: entry %q has unrecognized risk class %q", key, class)
		}
	}
	return nil
}
